namespace SF.Models;

/// <summary>
/// Target frameworks for generated projects. Only .NET 10 and later are supported.
/// Older values (0 to 10: .NET Framework 4.x, .NET Standard, .NET Core, .NET 6 and .NET 7) were removed;
/// models saved with them load as .NET 10. Add new versions with the next number (NET12 = 13).
/// </summary>
public enum TargetFrameworks
{
    NET10 = 11,
    NET11 = 12,
}
